<template>
  <section id="reportPrintArea">
    <div class="card"><div class="cardHead"><div><h3>Reports &amp; summaries</h3><div class="sub">Filter a period, then print, export or copy for submission</div></div><div class="flexrow no-print"><button class="btn" @click="exportCsv">CSV</button><button class="btn" @click="copyReport">Copy report text</button><button class="btn primary" @click="printArea('reportPrintArea')">Print</button></div></div>
      <div class="filterbar no-print"><div class="field"><label for="report-period">Report period</label><select id="report-period" v-model="state.report.preset" class="input" @change="saveUi"><option v-for="p in presets" :key="p[0]" :value="p[0]">{{ p[1] }}</option></select></div><div class="field"><label for="report-from">From</label><input id="report-from" v-model="state.report.from" class="input" type="date" @change="customRange"></div><div class="field"><label for="report-to">To</label><input id="report-to" v-model="state.report.to" class="input" type="date" @change="customRange"></div><div class="field"><label for="report-group">Group by</label><select id="report-group" v-model="state.report.group" class="input" @change="saveUi"><option v-for="g in groups" :key="g[0]" :value="g[0]">{{ g[1] }}</option></select></div></div>
      <div class="banner" style="margin-top:12px"><b>{{ state.settings.officeName }}</b> · Period: {{ periodLabel }} · {{ list.length }} entries in range</div><div v-if="invalidRange" class="err" role="alert">The end date cannot be earlier than the start date.</div>
    </div>
    <div class="kpis" style="margin-top:14px"><div v-for="k in kpis" :key="k.label" :class="['kpi',k.cls]"><div class="lab">{{ k.label }}</div><div class="val">{{ k.value }}</div><div class="small muted">{{ k.note }}</div></div></div>
    <div class="card" style="margin-top:14px"><div class="cardHead"><h3>Summary by {{ groupLabel.toLowerCase() }}</h3><div class="sub">{{ periodLabel }}</div></div><div v-if="!summary.length" class="empty"><b>No entries in this period</b>Pick a wider range or log new work.</div><div v-else class="tableWrap"><table class="tbl"><thead><tr><th>{{ groupLabel }}</th><th>Total</th><th>Accomplished</th><th>Ongoing</th><th>Pending</th><th>Overdue</th><th>Benef.</th><th>% done</th></tr></thead><tbody><tr v-for="g in summary" :key="g.name"><td><b>{{ g.name }}</b></td><td>{{ g.stats.total }}</td><td style="color:var(--done);font-weight:700">{{ g.stats.done }}</td><td>{{ g.stats.open }}</td><td>{{ g.stats.pend }}</td><td :class="{err:g.stats.overdue}">{{ g.stats.overdue }}</td><td>{{ g.stats.ben }}</td><td>{{ g.stats.rate }}%</td></tr></tbody></table></div></div>
    <div class="card" style="margin-top:14px"><div class="cardHead"><h3>Detailed listing</h3><div class="sub">{{ list.length }} entries — all included when printing or exporting</div></div><div v-if="!list.length" class="empty">Nothing to list.</div><div v-else class="tableWrap"><table class="tbl"><thead><tr><th>#</th><th>Work item</th><th>Category</th><th>Status</th><th>Date</th><th>Location</th><th>Personnel</th><th>Benef.</th></tr></thead><tbody><tr v-for="(e,i) in list" :key="e.id" :class="{overdueRow:isOverdue(e)}"><td>{{ i+1 }}</td><td><b>{{ e.title }}</b><div v-if="e.remarks" class="cellMeta">{{ e.remarks }}</div><div class="attrib">{{ e.createdByName ? 'Encoded by '+e.createdByName : '' }}</div></td><td>{{ e.category }}</td><td><span :class="['chip',isOverdue(e)?'late':e.status]">{{ STATUS[e.status].short }}{{ isOverdue(e)?' · overdue':'' }}</span></td><td class="nowrap">{{ fmtMed(plotDate(e)) }}</td><td>{{ e.location }}</td><td>{{ e.personnel }}</td><td>{{ e.beneficiaries || 0 }}</td></tr></tbody></table></div></div>
    <div v-if="reportTravels.length" class="card" style="margin-top:14px"><div class="cardHead"><h3>Official travel in period</h3></div><div class="tableWrap"><table class="tbl"><thead><tr><th>Traveller</th><th>Destination</th><th>Inclusive dates</th><th>Purpose</th></tr></thead><tbody><tr v-for="t in reportTravels" :key="t.id"><td>{{ t.travellerName }}</td><td>{{ t.destination }}</td><td>{{ fmtRange(t.from,t.to) }}</td><td>{{ t.purpose }}</td></tr></tbody></table></div></div>
    <div class="small muted" style="margin-top:16px">Prepared by: {{ state.auth.name }} · {{ state.settings.footer }}</div>
  </section>
</template>
<script setup>
import {computed,watch} from 'vue';
import {state,saveUi,notify} from '../../store/state';
import {isDate,fmtMed,fmtRange,todayISO} from '../../utils/dateUtils';
import {summarize,plotDate,isOverdue,reportRange,overlapsRange} from '../../utils/trackerMetrics';
import {STATUS} from '../../utils/constants';
import {entriesToCsv} from '../../utils/csvEngine';
import {downloadBinary} from '../../utils/storage';
import {printArea} from '../../utils/print';
const presets=[['month','This month (to date)'],['last-month','Last month'],['quarter','This quarter to date'],['year','This year to date'],['last-30','Last 30 days'],['all','All records'],['custom','Custom range…']];
const groups=[['category','Category'],['location','Location / Barangay'],['personnel','Personnel'],['status','Status'],['user','Recorded by (staff)'],['userdone','Accomplished by (staff)']];
const range=computed(()=>reportRange(state.report.preset,state.report.from,state.report.to));
watch(()=>state.report.preset,()=>{if(state.report.preset!=='custom'){const r=reportRange(state.report.preset);state.report.from=r.from;state.report.to=r.to;}},{immediate:true});
function customRange(){state.report.preset='custom';saveUi();}
const invalidRange=computed(()=>range.value.from&&range.value.to&&range.value.to<range.value.from);
const periodLabel=computed(()=>range.value.from||range.value.to ? `${range.value.from ? fmtMed(range.value.from) : 'Beginning'} to ${range.value.to ? fmtMed(range.value.to) : 'Present'}` : 'All records');
const list=computed(()=>invalidRange.value ? [] : state.entries.filter(e=>{const d=plotDate(e);return isDate(d)&&(!range.value.from||d>=range.value.from)&&(!range.value.to||d<=range.value.to);}).sort((a,b)=>plotDate(a).localeCompare(plotDate(b))));
const stats=computed(()=>summarize(list.value));
const groupLabel=computed(()=>groups.find(g=>g[0]===state.report.group)?.[1]||'Category');
const summary=computed(()=>{const map=new Map();for(const e of list.value){const name=state.report.group==='status'?STATUS[e.status].short:state.report.group==='user'?e.createdByName:state.report.group==='userdone'?e.completedByName:e[state.report.group];const names=state.report.group==='personnel'||state.report.group==='location' ? String(name||'Unspecified').split(',').map(s=>s.trim()).filter(Boolean) : [name||'Unspecified'];for(const n of new Set(names)){if(!map.has(n))map.set(n,[]);map.get(n).push(e);}}return [...map].map(([name,items])=>({name,stats:summarize(items)})).sort((a,b)=>b.stats.total-a.stats.total);});
const reportTravels=computed(()=>invalidRange.value?[]:state.travels.filter(t=>overlapsRange(t,range.value.from,range.value.to)));
const kpis=computed(()=>[{label:'Entries in period',value:stats.value.total},{label:'Encoded by me',value:list.value.filter(e=>e.createdBy===state.auth.id).length},{label:'Accomplished',value:stats.value.done,note:stats.value.rate+'% completion rate',cls:'done'},{label:'Ongoing + pending',value:stats.value.open+stats.value.pend,cls:'open'},{label:'Overdue',value:stats.value.overdue,cls:'late'},{label:'Beneficiaries served',value:stats.value.ben},{label:'Cancelled / deferred',value:stats.value.cancel,note:'Excluded from completion rate'}]);
function exportCsv(){downloadBinary(`ABE-Report-${todayISO()}.csv`,new TextEncoder().encode(entriesToCsv(list.value)),'text/csv');}
async function copyReport(){const text=[state.settings.officeName,state.settings.tagline,'WORK & ACCOMPLISHMENT REPORT','Period: '+periodLabel.value,`${stats.value.total} entries · ${stats.value.done} accomplished · ${stats.value.open+stats.value.pend} unfinished · ${stats.value.overdue} overdue · ${stats.value.ben} beneficiaries`,'',...summary.value.map(g=>`${g.name}: ${g.stats.total} total, ${g.stats.done} accomplished, ${g.stats.open} ongoing, ${g.stats.pend} pending, ${g.stats.overdue} overdue, ${g.stats.ben} beneficiaries`),'',...list.value.map(e=>`${fmtMed(plotDate(e))} · ${e.title} [${STATUS[e.status].short}] — ${e.location||'—'} — ${e.personnel||'—'}${e.remarks?'\n  '+e.remarks:''}`),'',...reportTravels.value.map(t=>`Travel: ${t.travellerName} → ${t.destination} · ${fmtRange(t.from,t.to)} · ${t.purpose}`),'','Prepared by: '+state.auth.name].join('\n');try{await navigator.clipboard.writeText(text);notify('Report text copied.');}catch(e){notify('Clipboard access failed. Use CSV or Print to export this report.',true);}}
</script>
